namespace docking.widgets.table.threaded;



using docking.widgets.filter;
using docking.widgets.table;
using docking.widgets.table;
using ghidra.docking.spy;

public class SpyTextFilter<T> : TableTextFilter<T> {

	private volatile bool hasFiltered = false;
	private AtomicInteger filterCount = new AtomicInteger(0);
	private SpyEventRecorder recorder;

	SpyTextFilter(TextFilter textFilter, RowFilterTransformer<T> transformer) : this(textFilter, transformer, new SpyEventRecorder("Stub"))
    {
	}

	SpyTextFilter(TextFilter textFilter, RowFilterTransformer<T> transformer,
			SpyEventRecorder recorder) : base(textFilter, transformer)
    {
		this.recorder = recorder;
		recorder.record("Created new " + getClass().getSimpleName());
	}

	/* @Override */
	public bool acceptsRow(T rowObject) {

		filterCount.incrementAndGet();

		if (!hasFiltered) {
			recorder.record("Model - filter started");
		}
		hasFiltered = true;
		return base.acceptsRow(rowObject);
	}

	bool hasFiltered() {
		return hasFiltered;
	}

	int getFilterCount() {
		return filterCount.get();
	}

	void reset() {
		recorder.record("Test - filter spy reset");
		hasFiltered = false;
		filterCount.set(0);
	}

	void dumpEvents() {
		recorder.dumpEvents();
	}
}
